// Comprueba el token compartido (X-Monitor-Token = $env.REVEL_GUARDIA_TOKEN) y
// prepara la lista de user_ids para enriquecer con la tabla Users, igual que
// el workflow de alertas de pagos.
const item = $input.first().json;
const expected = $env.REVEL_GUARDIA_TOKEN || '';
const given = (item.headers && (item.headers['x-monitor-token'] || item.headers['X-Monitor-Token'])) || '';
if (expected && given !== expected) {
  return [];
}
const body = item.body || item;
const userIds = (body.userIds || []).map((x) => String(x)).filter((x) => /^\d+$/.test(x)).slice(0, 20);
return [{ json: { ...body, userIds } }];

// Arma el mensaje de Slack con el diagnóstico de la IA y los usuarios afectados.
const alert = $('Validar token').first().json;
const users = $input.all().map((i) => i.json).filter((u) => u && u.id !== undefined);
const i = alert.issue || {};
const d = alert.diagnosis;
const icon = { critical: ':red_circle:', high: ':large_orange_circle:', medium: ':large_yellow_circle:' }[i.severity] || ':white_circle:';
const why = { new: 'Nueva', regression: 'Regresión', spike: 'Pico', diagnosed: 'Diagnosticada' }[alert.reason] || 'Alerta';
const lines = [];
lines.push(`${icon} *${why}: ${i.title}*`);
if (i.route) lines.push(`\`${i.route}\` → ${i.status || ''}`);
lines.push(`${i.count} ocurrencia(s), última ${i.lastSeen}${i.afterRelease ? ` · tras ${i.afterRelease}` : ''}${i.regression ? ' · estaba resuelta' : ''}`);
if (d) {
  lines.push(`\n*Qué pasa:* ${d.summary}`);
  lines.push(`*Causa:* ${d.rootCause}`);
  lines.push(`*Arreglo:* ${d.fix}`);
  if (d.location && d.location.file) lines.push(`*Dónde:* \`${d.location.file}${d.location.line ? ':' + d.location.line : ''}\``);
  lines.push(`_Confianza ${Math.round((d.confidence || 0) * 100)} %_`);
}
if (users.length) {
  lines.push('\n*Usuarios afectados:*');
  for (const u of users.slice(0, 10)) lines.push(`• user_id=${u.id} - ${u.name || ''} ${u.surname || ''} <${u.email || ''}>`);
} else if ((alert.userIds || []).length) {
  lines.push(`\nuser_ids: ${alert.userIds.join(', ')}`);
}
if (i.url) lines.push(`\n<${i.url}|Abrir en Revel Guardia>`);
return [{ json: { text: lines.join('\n') } }];
